    return str_pad($text, $width, ' ', STR_PAD_BOTH);
}

requirements.referenceSolution:
function padCenterUnicode(string $text, int $width): string {
    $len = mb_strlen($text, 'UTF-8');
    if ($len >= $width) {
        return $text;
    }
    $total = $width - $len;
    $left = intdiv($total, 2);
    $right = $total - $left;
    return str_repeat(' ', $left) . $text . str_repeat(' ', $right);
}

