public static List<Func<int>> MakeCounters(int n)
{
    var fs = new List<Func<int>>();
    for (int i = 1; i <= n; i++)
    {
        int c = i; // 每次迭代捕获独立副本
        fs.Add(() => c);
    }
    return fs;
}

