requirements.referenceSolution:
static boolean hasSettled(java.util.List<java.math.BigDecimal> ledger, java.math.BigDecimal amount) {
    for (java.math.BigDecimal v : ledger) {
        if (v.compareTo(amount) == 0) {
            return true;
        }
    }
    return false;
}

