requirements.referenceSolution:
static String normalizeDate(String s) {
    try {
        java.text.SimpleDateFormat f = new java.text.SimpleDateFormat("yyyy-MM-dd");
        f.setLenient(false);
        return f.format(f.parse(s));
    } catch (java.text.ParseException e) {
        return null;
    }
}
